:root {
    --background-dark: #1e1e1e;
    --text-dark: #d4d4d4;
    --primary-dark: #007acc;
    --secondary-dark: #333333;
    --border-dark: #444444;
    --code-background-dark: #2a2a2a;
}

body {
    margin: 0;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: var(--background-dark);
    color: var(--text-dark);
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    overflow: hidden;
}

.editor-container {
    width: 95%;
    height: 95vh;
    display: flex;
    flex-direction: column;
    border: 1px solid var(--border-dark);
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
    overflow: hidden;
    background-color: var(--background-dark);
}

.toolbar {
    padding: 10px;
    background-color: var(--secondary-dark);
    border-bottom: 1px solid var(--border-dark);
    display: flex;
    gap: 5px;
}

.toolbar button {
    background-color: var(--background-dark);
    color: var(--text-dark);
    border: 1px solid var(--border-dark);
    padding: 8px 12px;
    cursor: pointer;
    border-radius: 4px;
    font-size: 14px;
    transition: background-color 0.2s ease;
}

.toolbar button:hover {
    background-color: var(--primary-dark);
}

.split-screen {
    display: flex;
    flex-grow: 1;
    overflow: hidden;
}

.pane {
    flex: 1;
    padding: 15px;
    overflow-y: auto;
    box-sizing: border-box;
}

.left-pane {
    border-right: 1px solid var(--border-dark);
    display: flex;
    flex-direction: column;
}

#markdown-input {
    width: 100%;
    height: 100%;
    background-color: var(--background-dark);
    color: var(--text-dark);
    border: none;
    resize: none;
    font-family: 'Consolas', 'Monaco', 'Andale Mono', 'Ubuntu Mono', monospace;
    font-size: 16px;
    line-height: 1.6;
    outline: none;
    padding: 0;
    box-sizing: border-box;
}

.right-pane {
    background-color: var(--background-dark);
    padding: 20px;
}

#html-preview {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    line-height: 1.7;
}

#html-preview h1, #html-preview h2, #html-preview h3 {
    color: var(--primary-dark);
    margin-top: 1.5em;
    margin-bottom: 0.5em;
}

#html-preview h1 {
    font-size: 2em;
}

#html-preview h2 {
    font-size: 1.75em;
}

#html-preview h3 {
    font-size: 1.5em;
}

#html-preview p {
    margin-bottom: 1em;
}

#html-preview a {
    color: var(--primary-dark);
    text-decoration: none;
}

#html-preview a:hover {
    text-decoration: underline;
}

#html-preview code {
    background-color: var(--code-background-dark);
    padding: 2px 6px;
    border-radius: 3px;
    font-family: 'Consolas', 'Monaco', 'Andale Mono', 'Ubuntu Mono', monospace;
}

#html-preview pre {
    background-color: var(--code-background-dark);
    padding: 10px;
    border-radius: 5px;
    overflow-x: auto;
}

#html-preview pre code {
    background-color: transparent;
    padding: 0;
}

#html-preview strong {
    font-weight: bold;
}

#html-preview em {
    font-style: italic;
}

.status-bar {
    background-color: var(--secondary-dark);
    padding: 8px 15px;
    font-size: 13px;
    display: flex;
    justify-content: flex-end;
    gap: 20px;
    border-top: 1px solid var(--border-dark);
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .split-screen {
        flex-direction: column;
    }
    .pane {
        flex: none;
        width: 100%;
        height: 50%;
        overflow-y: auto;
    }
    .left-pane {
        border-right: none;
        border-bottom: 1px solid var(--border-dark);
    }
    .editor-container {
        height: 100vh;
        width: 100%;
    }
    .toolbar {
        flex-wrap: wrap;
        justify-content: center;
    }
}

/**
 * Calculates word and character counts from a given text.
 * @param {string} text The input text.
 * @returns {{wordCount: number, charCount: number}}
 */
function calculateCounts(text) {
    const charCount = text.length;
    const words = text.trim().split(/\s+/);
    const wordCount = words.length === 1 && words[0] === '' ? 0 : words.length;
    return { wordCount, charCount };
}

/**
 * Parses Markdown text to HTML using the 'marked' library.
 * @param {string} markdownText The Markdown string to parse.
 * @returns {string} The rendered HTML string.
 */
function parseMarkdown(markdownText) {
    // Ensure marked is available globally (loaded via CDN)
    if (typeof marked === 'undefined') {
        console.error('Marked.js library not loaded.');
        return '<p>Error: Markdown parser not available.</p>';
    }
    // Sanitize HTML output to prevent XSS attacks
    // Marked.js has built-in sanitization options, but for simplicity and
    // assuming a trusted environment or basic usage, we'll use default.
    // For production, consider configuring marked.js with a sanitizer.
    return marked.parse(markdownText);
}

/**
 * Manages the application's theme, specifically the dark theme.
 */
class ThemeManager {
    constructor() {
        this.isDarkMode = true; // Default to dark mode
        this.applyTheme();
    }

    applyTheme() {
        if (this.isDarkMode) {
            document.body.classList.add('dark-theme');
            document.body.classList.remove('light-theme');
        } else {
            document.body.classList.add('light-theme');
            document.body.classList.remove('dark-theme');
        }
    }

    toggleTheme() {
        this.isDarkMode = !this.isDarkMode;
        this.applyTheme();
    }
}

